import{_ as e,c as i,o as r,ah as l}from"./chunks/framework.Dnh4IO1K.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"易経ライフガイド","text":"AIで問い、原典で深く学ぶ","tagline":"卦を立て、解釈し、古典を読み、4096通りの変化をたどる。易経を日々使える知恵へ。","image":{"src":"/IChingStudy.png","alt":"I Ching: Yi Jing Life Guide App"}},"features":[{"title":"AIによる卦の解釈","details":"あなたの問いをもとに、卦意、動爻、之卦、状況の流れをAIと一緒に整理できます。"},{"title":"易経原典リーダー","details":"周易、易伝、注釈書などを集中して読めるリーダーを搭載。読書進捗や文字設定にも対応します。"},{"title":"4096の変化関係","details":"64×64の本卦→之卦を探索し、動爻が状況をどのように変えるかを視覚的に理解できます。"},{"title":"コースとクイズ","details":"六十四卦、卦辞、爻辞、象意をコースと練習問題で少しずつ身につけられます。"}]},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md"}'),t={name:"ja/index.md"};function n(o,a,s,h,d,p){return r(),i("div",null,[...a[0]||(a[0]=[l('<h2 id="占うだけで終わらない、易経の学習アプリ" tabindex="-1">占うだけで終わらない、易経の学習アプリ <a class="header-anchor" href="#占うだけで終わらない、易経の学習アプリ" aria-label="Permalink to “占うだけで終わらない、易経の学習アプリ”">​</a></h2><p><strong>I Ching: Yi Jing Life Guide</strong> は、AI 解釈、易経原典の読書、六十四卦の学習、変化ネットワーク、コース、クイズ、メモを一つにまとめた易経アプリです。</p><p>判断に迷ったときの内省にも、易経を体系的に学びたいときにも使えます。単なる占い結果ではなく、卦の構造、動爻の意味、変化の方向を理解するための道具です。</p><p>「易経 アプリ」「I Ching app」「Yi Jing」「Book of Changes」「六十四卦」「AI 解釈」を探している人に向けて、古典と現代的な学習体験をつなげます。</p><h2 id="主な機能" tabindex="-1">主な機能 <a class="header-anchor" href="#主な機能" aria-label="Permalink to “主な機能”">​</a></h2><ul><li><strong>AI 解釈</strong>：問いを入力し、卦、動爻、之卦、現実の文脈を整理します。</li><li><strong>複数の起卦方法</strong>：大衍筮法、三枚コイン、一爻成卦、高島略筮などに対応。</li><li><strong>古典読書</strong>：易経の原典や注釈を、落ち着いたリーダーで読めます。</li><li><strong>六十四卦の学習</strong>：卦辞、象辞、爻辞、八卦の構造を確認できます。</li><li><strong>4096の変化マップ</strong>：すべての本卦→之卦の組み合わせを探索できます。</li><li><strong>コース、クイズ、メモ</strong>：一度きりの占いではなく、長期的な理解を育てます。</li></ul><h2 id="こんな人におすすめ" tabindex="-1">こんな人におすすめ <a class="header-anchor" href="#こんな人におすすめ" aria-label="Permalink to “こんな人におすすめ”">​</a></h2><ul><li>易経を使って考えを整理したい人</li><li>六十四卦を基礎から学びたい人</li><li>原典や注釈を読み比べたい人</li><li>AI 解釈と古典読書を同じ場所で使いたい人</li><li>単純な占いアプリでは物足りない人</li></ul><h2 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to “よくある質問”">​</a></h2><h3 id="占いアプリですか" tabindex="-1">占いアプリですか？ <a class="header-anchor" href="#占いアプリですか" aria-label="Permalink to “占いアプリですか？”">​</a></h3><p>卦を立てて解釈できますが、目的は単なる占いではありません。易経を使って状況を見つめ直し、学びを深めるためのアプリです。</p><h3 id="初心者でも使えますか" tabindex="-1">初心者でも使えますか？ <a class="header-anchor" href="#初心者でも使えますか" aria-label="Permalink to “初心者でも使えますか？”">​</a></h3><p>はい。AI 解説、コース、クイズ、卦の参照機能があるため、易経を初めて学ぶ人にも使いやすく設計されています。</p><h3 id="上級者にも役立ちますか" tabindex="-1">上級者にも役立ちますか？ <a class="header-anchor" href="#上級者にも役立ちますか" aria-label="Permalink to “上級者にも役立ちますか？”">​</a></h3><p>はい。原典読書、4096の変化関係、易林、高島易断など、より深く学ぶための内容も用意されています。</p><h3 id="判断を代わりにしてくれますか" tabindex="-1">判断を代わりにしてくれますか？ <a class="header-anchor" href="#判断を代わりにしてくれますか" aria-label="Permalink to “判断を代わりにしてくれますか？”">​</a></h3><p>いいえ。易経は内省の鏡として使うものです。このアプリは学習、参考、自己理解のためのツールであり、投資、医療、法律、予言の助言ではありません。</p><h2 id="ダウンロード" tabindex="-1">ダウンロード <a class="header-anchor" href="#ダウンロード" aria-label="Permalink to “ダウンロード”">​</a></h2><p>App Store で <strong>I Ching: Yi Jing Life Guide</strong> をダウンロードし、易経を日々の学びと内省のための道具にしてください。</p>',19)])])}const f=e(t,[["render",n]]);export{g as __pageData,f as default};
